import{_ as i,o as l,c as o,a7 as a}from"./chunks/framework.DUCm5Bu5.js";const p=JSON.parse('{"title":"更新日志","description":"面向公开版本的带日期变更记录。","frontmatter":{"title":"更新日志","description":"面向公开版本的带日期变更记录。","updated":"2026-10-25T00:00:00.000Z"},"headers":[],"relativePath":"project/changelog.md","filePath":"project/changelog.md"}'),t={name:"project/changelog.md"};function c(d,e,r,n,s,u){return l(),o("div",null,[...e[0]||(e[0]=[a('<h2 id="未发布-—-2026-10-25-utc-08-00" tabindex="-1">未发布 — 2026-10-25（UTC+08:00） <a class="header-anchor" href="#未发布-—-2026-10-25-utc-08-00" aria-label="Permalink to &quot;未发布 — 2026-10-25（UTC+08:00）&quot;">​</a></h2><ul><li>2026-10-25：恢复全部 22 组已配置的 kr-1256 AI 房间预设，包含阵容等级、角色、颜色、服装、武器与原生物品修改器。房间与回合视图中的 AI 昵称按每位接收者的启动器语言显示；韩语名称保留预设拼写，其他语言使用本地化的难度标题与角色名。修改器目标无效、本地化缺失或外观数据超限时在激活阶段失败。实际进游戏的外观验收仍待完成。</li><li>2026-10-25：通过原生添加/移除请求加入可选的 kr-1256 AI 房间席位，包含独立的席位外观记录、控制者迁移以及按角色的移动、计分与生命/重置状态。机器人保留席位但不占用网络会话，也不会阻塞人类玩家的加载屏障。可选的 <code>profiles/kr-1256/ai-rooms.patch.yaml</code> 为原生预设选择提供可配置的服务器配装；完整官方装扮与真实客户端玩法验收仍未验证。初始教学关卡路线不变。</li><li>2026-10-25：移除未使用的 <code>match-relay</code> 插件与 <code>InGame.Wire</code> 程序集。共用房间绑定改经封包表读写回合结果；房间会话模型移入房间库，中继会话键移入契约程序集。既有的类型化玩法路径与 profile 配置保持不变。</li><li>2026-10-24：把最后的兼容插件并入共用行。删除的插件 ID：<code>dialect.modern.messages</code>、<code>dialect.inventory-actions</code> 与 <code>dialect.customized-keys</code>；其封包改为 <code>dialect.messages</code> 的选项（<code>inventory_actions</code>、<code>customized_keys</code>）。封包字节无变化；补丁中列出任何被删除行的运营者必须删除该行，否则 profile 组合会以未知插件名失败。</li></ul><h2 id="未发布-—-2026-10-20-utc-08-00" tabindex="-1">未发布 — 2026-10-20（UTC+08:00） <a class="header-anchor" href="#未发布-—-2026-10-20-utc-08-00" aria-label="Permalink to &quot;未发布 — 2026-10-20（UTC+08:00）&quot;">​</a></h2><ul><li>2026-10-22：新增启动器自建商店指南，说明总目录、客户端 Profile、插件元数据、工具依赖与限制，以及总目录最后发布的流程。</li><li>每个版本都会发布 Windows x64、Windows ARM64、Linux x64 与 Linux arm64 的预编译包。在 Windows 上解压 ZIP 后双击 <code>BubbleFighter.Fantasy.Host.exe</code>：安装向导随即启动并在浏览器中打开，启动出错时错误会一直显示到按下任意键。在 Linux 上，<code>curl -fsSL https://wasabi-fantasytaledev.github.io/install.sh | bash</code> 即可安装服务器，加上 <code>--docker</code> 则在容器中运行，只有再加上 <code>--with-mysql</code> 时才附带 MySQL。</li><li>KR2026 的商店购买遵循客户端自身商店表中的物品条款：限时物品会到期，永久物品保持永久，条款拒绝的购买会收到失败回复且不扣费。含有耐久计数物品的六个套装在该版本的规则确定之前暂时无法购买。</li><li>KR2026 商店的所有封包现在都按名称从该版本的 opcode 表查找。打开礼物盒的已发送列表不再触发购买，退款请求也不再收到物品卡片的应答。</li><li>KR2026 的新账号现在会进入客户端自带的角色创建画面，与旧版本一致。KR2026 也会在玩家离线期间物品到期后显示原生的到期通知。</li><li>修复旧版本中持有未记录期限物品的账号无法登录的问题，以及 cn-404、cn-406、cn-408 与 cn-706 的首次登录问题。</li><li>KR2026、cn-774 与 tw-454 改由共用的登录适配器登录。使用自定义补丁的运营者请注意：已移除的 <code>dialect.modern.messages</code> 登录选项列在仓库的 <code>CHANGELOG.md</code> 中；补丁中仍有已移除的键时，启动会失败，删除后即可恢复。</li><li>启动检查现在会验证绑定读写的每个封包字段的类型，因此封包表若改变了字段类型，会在服务器启动时报错，而不是在收到第一个封包时出错。</li><li>故障排查页说明了 <code>NU1900</code> 包审计错误，以及无法连接 nuget.org 时如何构建。</li></ul><h2 id="未发布-—-2026-10-18-utc-08-00" tabindex="-1">未发布 — 2026-10-18（UTC+08:00） <a class="header-anchor" href="#未发布-—-2026-10-18-utc-08-00" aria-label="Permalink to &quot;未发布 — 2026-10-18（UTC+08:00）&quot;">​</a></h2><ul><li>扩充四语言指南并补齐可验证步骤：安装与快速开始区分源码构建与尚未发布的构建包；配置记录 profile 组合、环境变量、端口、持久化与客户端数据；部署覆盖 Docker Compose、备份、升级与回退；故障排查按「症状 → 检查 → 原因 → 处理」组织。</li><li>插件指南新增可实际执行的第一个插件流程；SDK 协议参考新增各语言快速上手、能力协商与一致性测试内容。</li><li>重写中英文 README，补充环境要求、Windows 与 Linux 快速开始、Docker Compose、客户端数据边界与文档入口。</li><li>修正与当前代码不符的描述；尚未发布的下载与安装入口继续标注为即将提供。本次仅涉及文档，运行行为没有改变。</li><li>新增四语言「启动器」指南：配套 Fantasy Tale Launcher 的客户端版本、会话与登录票据模型、hook 插件、分发边界，以及面向运营者的服务端 <code>launcher.http</code> API，包括 HTTP 426 版本门禁、JSON 兼容规则与票据安全边界。仅涉及文档。</li></ul><h2 id="未发布-—-2026-10-16-utc-08-00" tabindex="-1">未发布 — 2026-10-16（UTC+08:00） <a class="header-anchor" href="#未发布-—-2026-10-16-utc-08-00" aria-label="Permalink to &quot;未发布 — 2026-10-16（UTC+08:00）&quot;">​</a></h2><ul><li>增加原生事件总线上的声明式 SDK 事件，支持跨语言串行/并行通知、waterfall 拦截与 bail 决策。</li><li>保留事件续调的所有权并完善 Rust 回调清理；修复关闭时可能遗漏已记录激活超时的竞争问题。</li><li>为 Python、TypeScript、Go 和 Rust 增加 SDK 服务提供者、装饰链及有序服务集合，包含 Go/Rust WebAssembly。</li><li>取消和超时后保留已进入工作的所有权，修正发布新定义后的启动选择。</li><li>插件行超时后仍执行 SDK 清理；共享进程继续存活时，允许回收已退役的激活上下文。</li><li>在插件与 SDK 指南中补充注册示例、生命周期规则和仍未实现的原生对等能力。</li></ul><h2 id="未发布-—-2026-10-15-utc-08-00" tabindex="-1">未发布 — 2026-10-15（UTC+08:00） <a class="header-anchor" href="#未发布-—-2026-10-15-utc-08-00" aria-label="Permalink to &quot;未发布 — 2026-10-15（UTC+08:00）&quot;">​</a></h2><ul><li>准备新的公开文档与 Vue 3 四语言文档站。</li><li>增加 Windows x64/ARM64 下载入口与 Linux 安装脚本/Docker 选项；下载地址仍为即将提供。</li><li>修正私有文件排除规则，将内部工具移出公开源码索引。</li><li>公开门禁保留 Equipment、Shop 内可独立运行的测试，只明确筛出本地数据用例。</li><li>保留既有 bootstrap 默认值；本地目录数据缺失时明确失败，不再记录为测试通过。</li></ul><p>这是首个公开版本的准备记录，不代表构建包或文档站已发布。详细变更在仓库根目录的中英文更新日志中维护。</p>',11)])])}const m=i(t,[["render",c]]);export{p as __pageData,m as default};
